90→      }

    case MSG.RUN_FULL:
      return runFullScrape({
        reason: msg.reason || 'manual',
        tabId: msg.tabId,
        dryRun: msg.dryRun
      });

    case MSG.WRITE_FEISHU:
100→      return writeOnly(msg.rows || [], { dryRun: msg.dryRun });

    default:
      return { ok: false, error: `unknown type: ${msg.type}` };
  }
